const ids = new Set()
const catalog = []
for (const group of groups) {
  for (const [position, row] of group.rows.entries()) {
    const [title, theme, detail, durationMinutes, energy, setting, materials, preparation, lowEnergyAlternative, accessExtra = '', consentExtra = ''] = row
    const number = catalog.length + 1
    const id = `${String(number).padStart(2, '0')}-${title.normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
    if (ids.has(id)) throw new Error(`Duplicate ID: ${id}`)
    ids.add(id)
    const bank = group.questions
    const prompts = Array.from({ length: 5 }, (_, offset) => bank[(position + offset) % bank.length](theme))
    const steps = group.steps(detail)
    catalog.push({
      id, title, category: group.category,
      description: `${detail} Pueden ajustar la duración o cambiar de idea en cualquier momento.`,
      objective: group.objective(theme),
      durationMinutes, energy, setting, materials, preparation, steps, prompts, lowEnergyAlternative,
      accessibility: [group.commonAccess, ...(accessExtra ? [accessExtra] : [])],
      consent: [group.commonConsent, ...(consentExtra ? [consentExtra] : [])],
      enjoymentTips: group.tip,
    })
  }
}

const expected = [15, 20, 20, 15, 15, 15]
if (catalog.length !== 100 || groups.some((group, index) => group.rows.length !== expected[index])) throw new Error('Catalog category totals are not 15/20/20/15/15/15.')
await writeFile(new URL('../catalog/dates.json', import.meta.url), `${JSON.stringify(catalog, null, 2)}\n`, 'utf8')
console.log(`Wrote ${catalog.length} catalog items in ${groups.length} categories.`)
